import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Code Agent 执行规范","description":"","frontmatter":{"title":"Code Agent 执行规范"},"headers":[],"relativePath":"zh/guide/agent-protocol.md","filePath":"zh/guide/agent-protocol.md","lastUpdated":0}`),a={name:`zh/guide/agent-protocol.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_15-code-agent-的执行规范" tabindex="-1">15. Code Agent 的执行规范 <a class="header-anchor" href="#_15-code-agent-的执行规范" aria-label="Permalink to “15. Code Agent 的执行规范”">​</a></h1><h2 id="_15-1-不允许直接根据文档一次性生成全部项目" tabindex="-1">15.1 不允许直接根据文档一次性生成全部项目 <a class="header-anchor" href="#_15-1-不允许直接根据文档一次性生成全部项目" aria-label="Permalink to “15.1 不允许直接根据文档一次性生成全部项目”">​</a></h2><p>必须分阶段实现。</p><p>每个阶段先检查当前仓库状态，再创建任务清单和实施计划。</p><p>如果仓库已经存在代码：</p><ul><li>不得覆盖已有有效实现。</li><li>不得假设之前的架构已经过时。</li><li>必须分析现有调用路径和模块依赖。</li><li>先识别兼容性影响，再决定重构范围。</li><li>保留已有测试并补充回归测试。</li></ul><h2 id="_15-2-每个任务必须输出" tabindex="-1">15.2 每个任务必须输出 <a class="header-anchor" href="#_15-2-每个任务必须输出" aria-label="Permalink to “15.2 每个任务必须输出”">​</a></h2><ol><li>修改文件清单。</li><li>修改原因。</li><li>接口变更。</li><li>状态机影响。</li><li>数据库迁移影响。</li><li>平台兼容性影响。</li><li>安全影响。</li><li>新增测试。</li><li>执行的验证命令。</li><li>验收结果。</li><li>未解决的问题。</li></ol><p>不能只提交代码而没有说明验证结果。</p><h2 id="_15-3-agent-的工作顺序" tabindex="-1">15.3 Agent 的工作顺序 <a class="header-anchor" href="#_15-3-agent-的工作顺序" aria-label="Permalink to “15.3 Agent 的工作顺序”">​</a></h2><p>每个阶段遵循：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Inspect Repository</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Create Implementation Plan</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Define Interfaces</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Implement Minimal Vertical Slice</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Add Unit Tests</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Add Integration Tests</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Run Formatting and Linting</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Run Test Suite</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Review Security and Failure Paths</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Update Documentation</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Report Results</span></span></code></pre></div><p>每个阶段必须在测试通过后再进入下一阶段。</p><h2 id="_15-4-建议的首批任务" tabindex="-1">15.4 建议的首批任务 <a class="header-anchor" href="#_15-4-建议的首批任务" aria-label="Permalink to “15.4 建议的首批任务”">​</a></h2><h3 id="task-001-领域模型" tabindex="-1">Task 001：领域模型 <a class="header-anchor" href="#task-001-领域模型" aria-label="Permalink to “Task 001：领域模型”">​</a></h3><p>实现 Resource、Dependency、HealthStatus、Evidence、Diagnosis、RecoveryPolicy、RecoveryRun、RecoveryAction、VerificationResult 和 AuditEvent。</p><p>交付：</p><ul><li>类型定义。</li><li>状态转换规则。</li><li>序列化和反序列化测试。</li><li>不合法状态转换测试。</li><li>领域模型文档。</li></ul><h3 id="task-002-配置与依赖图" tabindex="-1">Task 002：配置与依赖图 <a class="header-anchor" href="#task-002-配置与依赖图" aria-label="Permalink to “Task 002：配置与依赖图”">​</a></h3><p>实现配置解析、引用验证、依赖图构建、循环检测和依赖条件验证。</p><p>交付：</p><ul><li>配置 Schema 或等效验证规则。</li><li>依赖图算法。</li><li>错误路径定位。</li><li>正常、缺失依赖、重复 ID 和循环依赖测试。</li></ul><h3 id="task-003-恢复状态机" tabindex="-1">Task 003：恢复状态机 <a class="header-anchor" href="#task-003-恢复状态机" aria-label="Permalink to “Task 003：恢复状态机”">​</a></h3><p>实现 RecoveryRun 状态转换、恢复预算、资源级互斥、动作执行和验证闭环。</p><p>交付：</p><ul><li>完整状态机。</li><li>失败后的重新诊断。</li><li>第二候选方案。</li><li>动作结果未知处理。</li><li>并发恢复测试。</li></ul><h3 id="task-004-sqlite-持久化" tabindex="-1">Task 004：SQLite 持久化 <a class="header-anchor" href="#task-004-sqlite-持久化" aria-label="Permalink to “Task 004：SQLite 持久化”">​</a></h3><p>实现数据库迁移、RecoveryRun 持久化、动作记录和恢复任务重启。</p><p>交付：</p><ul><li>数据库 Schema。</li><li>事务边界说明。</li><li>进程崩溃测试。</li><li>数据库迁移测试。</li><li>未完成任务恢复测试。</li></ul><h3 id="task-005-plugin-host" tabindex="-1">Task 005：Plugin Host <a class="header-anchor" href="#task-005-plugin-host" aria-label="Permalink to “Task 005：Plugin Host”">​</a></h3><p>实现 JSON-RPC stdio、插件生命周期、消息大小限制、超时和取消。</p><p>交付：</p><ul><li>插件协议文档。</li><li>示例插件。</li><li>协议测试。</li><li>大量输出测试。</li><li>插件崩溃和超时测试。</li></ul><h3 id="task-006-notification-engine" tabindex="-1">Task 006：Notification Engine <a class="header-anchor" href="#task-006-notification-engine" aria-label="Permalink to “Task 006：Notification Engine”">​</a></h3><p>实现事件规则、持久化队列、Webhook、SMTP、本地日志和发送重试。</p><p>交付：</p><ul><li>统一通知接口。</li><li>事件模型。</li><li>持久化队列。</li><li>渠道实现。</li><li>断网重试测试。</li><li>凭据脱敏测试。</li></ul><h3 id="task-007-cli" tabindex="-1">Task 007：CLI <a class="header-anchor" href="#task-007-cli" aria-label="Permalink to “Task 007：CLI”">​</a></h3><p>实现状态、资源、依赖图、故障历史、恢复历史和通知状态命令。</p><p>交付：</p><ul><li>CLI 命令。</li><li>错误输出规范。</li><li>帮助文档。</li><li>集成测试。</li></ul><h3 id="task-008-首个真实恢复场景" tabindex="-1">Task 008：首个真实恢复场景 <a class="header-anchor" href="#task-008-首个真实恢复场景" aria-label="Permalink to “Task 008：首个真实恢复场景”">​</a></h3><p>优先选择一个简单且可以自动验证的场景，例如受控进程退出后自动恢复。</p><p>随后实现代理与 Cloudflare Tunnel 场景，验证依赖恢复顺序。</p><p>交付：</p><ul><li>示例配置。</li><li>故障注入测试。</li><li>完整 RecoveryRun 记录。</li><li>恢复成功与失败的通知结果。</li></ul><hr>`,48)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};